#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *store;
    size_t capacity;
    size_t head;  /* write index */
    size_t tail;  /* read index */
    size_t count; /* current bytes stored */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb = NULL;

    if (capacity == 0)
        return NULL;

    rb = malloc(sizeof(*rb));
    if (!rb)
        return NULL;

    rb->store = malloc(capacity);
    if (!rb->store) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->store);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    size_t nwritten;

    if (!rb || !data || len == 0)
        return 0;

    nwritten = len;
    if (nwritten > rb->capacity - rb->count)
        nwritten = rb->capacity - rb->count;

    /* Figure out how much we can write contiguously from head */
    {
        size_t to_end = rb->capacity - rb->head;

        if (nwritten <= to_end) {
            memcpy(&rb->store[rb->head], data, nwritten);
            rb->head += nwritten;
        } else {
            memcpy(&rb->store[rb->head], data, to_end);
            rb->head = 0;
            /* remaining */
            nwritten -= to_end;
            memcpy(rb->store, data + to_end, nwritten);
            rb->head = nwritten;
        }
    }

    rb->count += nwritten;
    return nwritten;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t nread;

    if (!rb || !out || len == 0)
        return 0;

    nread = len;
    if (nread > rb->count)
        nread = rb->count;

    {
        size_t to_end = rb->capacity - rb->tail;

        if (nread <= to_end) {
            memcpy(out, &rb->store[rb->tail], nread);
            rb->tail += nread;
        } else {
            memcpy(out, &rb->store[rb->tail], to_end);
            rb->tail = 0;
            /* remaining */
            nread -= to_end;
            memcpy(out + to_end, rb->store, nread);
            rb->tail = nread;
        }
    }

    rb->count -= nread;
    return nread;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t npeeked;
    size_t to_end;

    if (!rb || !out || len == 0)
        return 0;

    npeeked = len;
    if (npeeked > rb->count)
        npeeked = rb->count;

    to_end = rb->capacity - rb->tail;

    if (npeeked <= to_end) {
        memcpy(out, &rb->store[rb->tail], npeeked);
    } else {
        memcpy(out, &rb->store[rb->tail], to_end);
        memcpy(out + to_end, rb->store, npeeked - to_end);
    }

    return npeeked;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->count;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
}

#include <stdio.h>
#include "ringbuf.h"

int main(void)
{
    int ok = 1;
    ringbuf_t *rb;

    /* basic create / capacity / size */
    rb = rb_create(8);
    if (!rb || rb_capacity(rb) != 8 || rb_size(rb) != 0) { printf("fail %s\n", __LINE__); ok = 0; }

    /* write and read round trip */
    uint8_t inp[] = {1,2,3,4,5};
    if (rb_write(rb, inp, 5) != 5 || rb_size(rb) != 5) { printf("fail %s\n", __LINE__); ok = 0; }

    uint8_t out[5] = {0};
    if (rb_read(rb, out, 10) != 5) { printf("fail %s\n", __LINE__); ok = 0; }
    for (int i = 0; i < 5; i++) { if (out[i] != (uint8_t)(i+1)) { printf("fail %s\n", __LINE__); ok = 0; break; } }

    /* wrap-around write */
    rb_clear(rb);
    uint8_t blk[] = "hello world";
    size_t w = rb_write(rb, blk, 12); /* buffer is only 8 bytes */
    if (w != 8 || rb_size(rb) != 8) { printf("fail %s\n", __LINE__); ok = 0; }

    uint8_t peeked[4] = {0};
    size_t p = rb_peek(rb, peeked, 4);
    if (p != 4 || peeked[0] != 'h' || peeked[3] != 'o') { printf("fail %s\n", __LINE__); ok = 0; }

    /* empty read */
    if (rb_read(rb, out, 1) != 8) { printf("fail %s\n", __LINE__); ok = 0; } /* read all 8 */

    /* NULL safety */
    rb_destroy(NULL);
    if (rb_write(NULL, inp, 1) != 0 || rb_read(NULL, out, 1) != 0) { printf("fail %s\n", __LINE__); ok = 0; }
    if (rb_size(NULL) != 0 || rb_capacity(NULL) != 0) { printf("fail %s\n", __LINE__); ok = 0; }

    /* invalid create */
    if (rb_create(0) != NULL) { printf("fail %s\n", __LINE__); ok = 0; }

    rb_destroy(rb);

    puts(ok ? "ALL OK" : "FAIL");
    return ok ? 0 : 1;
}

